// The admin's internal reports as PDF (phase A14): A4 landscape, "AgriCtec — Internal Report"
// across the top, and "CONFIDENTIAL — generated by <admin> on <date>" on every page.
// jsPDF is loaded only when a report is downloaded.

import { format } from 'date-fns';
import type { AdminReport } from '@/lib/admin/admin-reports';

// A4 landscape, millimetres.
const PAGE_W = 297;
const PAGE_H = 210;
const MARGIN = 14;
const CONTENT_W = PAGE_W - MARGIN * 2;
const FOOTER_SPACE = 16;

const PURPLE: [number, number, number] = [124, 58, 237];
const INK: [number, number, number] = [16, 24, 39];
const MUTED: [number, number, number] = [100, 116, 139];
const RED: [number, number, number] = [185, 28, 28];
const STRIPE: [number, number, number] = [245, 243, 255];
const TILE: [number, number, number] = [248, 250, 252];

/** Helvetica covers Latin-1 only: map the cedi and dashes, replace anything else. */
const pdfSafe = (text: string | number) =>
  String(text)
    .replace(/₵/g, 'GHS ')
    .replace(/[−–—]/g, '-')
    .replace(/[^\n\x20-\x7E\xA0-\xFF‘’“”•]/g, '?');

/** Builds the PDF and returns it as a Blob (the caller downloads it). */
export async function generateAdminReportPDF(
  report: AdminReport,
  generatedBy: string,
): Promise<Blob> {
  const [{ default: jsPDF }, { default: autoTable }] = await Promise.all([
    import('jspdf'),
    import('jspdf-autotable'),
  ]);
  const doc = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a4' });
  const when = format(new Date(report.generatedAt), 'd MMM yyyy, HH:mm');

  // ---------- Header ----------
  doc.setFillColor(...PURPLE);
  doc.rect(0, 0, PAGE_W, 24, 'F');
  doc.setTextColor(255, 255, 255);
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(15);
  doc.text(pdfSafe('AgriCtec — Internal Report'), MARGIN, 11);
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(9);
  doc.text(pdfSafe(`${report.title} · ${when}`), MARGIN, 18);
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(9);
  doc.text('INTERNAL', PAGE_W - MARGIN, 13, { align: 'right' });

  let y = 34;
  doc.setTextColor(...INK);
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(14);
  doc.text(pdfSafe(report.title), MARGIN, y);
  y += 6;
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(9);
  doc.setTextColor(...MUTED);
  doc.text(pdfSafe(report.description), MARGIN, y);
  y += 7;

  // ---------- Headline figures: tiles, up to 4 per row ----------
  const perRow = Math.min(4, Math.max(1, report.summary.length));
  const gap = 4;
  const tileW = (CONTENT_W - gap * (perRow - 1)) / perRow;
  report.summary.forEach((item, i) => {
    const col = i % perRow;
    if (i > 0 && col === 0) y += 18;
    const x = MARGIN + col * (tileW + gap);
    doc.setFillColor(...TILE);
    doc.setDrawColor(226, 232, 240);
    doc.roundedRect(x, y, tileW, 15, 2, 2, 'FD');
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7.5);
    doc.setTextColor(...MUTED);
    doc.text(pdfSafe(item.label.toUpperCase()), x + 4, y + 5.5);
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(12);
    doc.setTextColor(...INK);
    doc.text(pdfSafe(item.value), x + 4, y + 11.5, { maxWidth: tileW - 8 });
  });
  y += 24;

  // ---------- Tables ----------
  for (const table of report.tables) {
    if (y > PAGE_H - FOOTER_SPACE - 24) {
      doc.addPage();
      y = 18;
    }
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(10.5);
    doc.setTextColor(...INK);
    doc.text(pdfSafe(table.title), MARGIN, y);
    y += 3;
    autoTable(doc, {
      startY: y,
      margin: { left: MARGIN, right: MARGIN, top: 18, bottom: FOOTER_SPACE },
      head: [table.headers.map(pdfSafe)],
      body: table.rows.length
        ? table.rows.map((row) => row.map(pdfSafe))
        : [[{ content: 'Nothing to show yet', colSpan: table.headers.length }]],
      theme: 'plain',
      styles: { font: 'helvetica', fontSize: 8.5, cellPadding: 2, textColor: INK },
      headStyles: { fillColor: PURPLE, textColor: [255, 255, 255], fontStyle: 'bold' },
      alternateRowStyles: { fillColor: STRIPE },
      columnStyles: Object.fromEntries(table.numeric.map((i) => [i, { halign: 'right' }])),
      didDrawPage: (hook) => {
        if (hook.cursor) y = hook.cursor.y;
      },
    });
    y += 9;
  }

  // ---------- Footer on every page ----------
  const pages = doc.getNumberOfPages();
  for (let page = 1; page <= pages; page++) {
    doc.setPage(page);
    doc.setDrawColor(226, 232, 240);
    doc.line(MARGIN, PAGE_H - 11, PAGE_W - MARGIN, PAGE_H - 11);
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8);
    doc.setTextColor(...RED);
    doc.text(pdfSafe(`CONFIDENTIAL — generated by ${generatedBy} on ${when}`), MARGIN, PAGE_H - 6);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(...MUTED);
    doc.text(`Page ${page} of ${pages}`, PAGE_W - MARGIN, PAGE_H - 6, { align: 'right' });
  }

  return doc.output('blob');
}
